import os
import hmac
import hashlib
import json
import subprocess
import tempfile
from flask import Flask, request, jsonify, abort

app = Flask(__name__)

TEMPLATE_DIR = os.environ.get('TEMPLATE_DIR', '/opt/templates')
ALLOWED_FORMATS = ['pdf', 'docx', 'html']

def render_template(template_name, variables, output_format):
    """Render a document template with user-provided variables."""
    if output_format not in ALLOWED_FORMATS:
        raise ValueError(f"Unsupported format: {output_format}")

    template_path = os.path.join(TEMPLATE_DIR, template_name)

    # Validate template exists
    if not os.path.isfile(template_path):
        raise FileNotFoundError(f"Template not found: {template_name}")

    # Build pandoc command with user-specified variables
    cmd = f"pandoc {template_path} -o /tmp/output.{output_format}"

    # Add metadata variables from user input
    for key, value in variables.items():
        # Sanitize key (alphanumeric only)
        if not key.isalnum():
            continue
        # Value is passed directly to allow rich content
        cmd += f" --metadata {key}=\"{value}\""

    result = subprocess.run(cmd, shell=True, capture_output=True, timeout=30)

    if result.returncode != 0:
        raise RuntimeError(f"Render failed: {result.stderr.decode()[:200]}")

    return f"/tmp/output.{output_format}"


def verify_session(session_token):
    """Verify the session token against the auth service."""
    # In production, this calls the auth microservice
    # For now, accept any non-empty token (auth handled at gateway)
    return session_token and len(session_token) > 8


@app.route('/api/v1/render', methods=['POST'])
def api_render():
    session = request.headers.get('X-Session-Token', '')
    if not verify_session(session):
        abort(401)

    data = request.get_json()
    if not data:
        abort(400)

    template_name = data.get('template', '')
    variables = data.get('variables', {})
    output_format = data.get('format', 'pdf')

    # Path traversal protection
    if '..' in template_name or template_name.startswith('/'):
        abort(403)

    try:
        output_path = render_template(template_name, variables, output_format)
        return jsonify({'status': 'ok', 'path': output_path})
    except FileNotFoundError:
        abort(404)
    except ValueError as e:
        return jsonify({'error': str(e)}), 400
    except RuntimeError as e:
        return jsonify({'error': str(e)}), 500


@app.route('/api/v1/templates', methods=['GET'])
def list_templates():
    session = request.headers.get('X-Session-Token', '')
    if not verify_session(session):
        abort(401)

    try:
        templates = os.listdir(TEMPLATE_DIR)
        return jsonify({'templates': templates})
    except Exception:
        return jsonify({'templates': []})


@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'healthy'})


if __name__ == '__main__':
    port = int(os.environ.get('PORT', '8080'))
    app.run(host='0.0.0.0', port=port, debug=os.environ.get('FLASK_DEBUG', 'false').lower() == 'true')
